create table if not exists public.uniform_guide_sections (
  section_key text primary key,
  label text not null,
  description text not null default '',
  sort_order integer not null default 0,
  published boolean not null default true,
  updated_at timestamptz not null default now(),
  updated_by uuid references public.app_auth_users(id) on delete set null
);

create table if not exists public.uniform_guide_entries (
  id uuid primary key default gen_random_uuid(),
  entry_key text not null unique,
  section_key text not null references public.uniform_guide_sections(section_key) on delete cascade,
  title text not null,
  subtitle text not null default '',
  summary text not null default '',
  categories jsonb not null default '[]'::jsonb check (jsonb_typeof(categories) = 'array'),
  notes text[] not null default '{}',
  links jsonb not null default '[]'::jsonb check (jsonb_typeof(links) = 'array'),
  image_path text,
  sort_order integer not null default 0,
  published boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  updated_by uuid references public.app_auth_users(id) on delete set null
);

create table if not exists public.uniform_guide_assets (
  id uuid primary key default gen_random_uuid(),
  file_name text not null,
  mime_type text not null check (mime_type in ('image/png', 'image/jpeg', 'image/webp')),
  byte_size integer not null check (byte_size > 0 and byte_size <= 5242880),
  sha256 text not null,
  contents bytea not null,
  uploaded_at timestamptz not null default now(),
  uploaded_by uuid references public.app_auth_users(id) on delete set null
);

create table if not exists public.uniform_guide_revisions (
  id bigserial primary key,
  entry_id uuid references public.uniform_guide_entries(id) on delete set null,
  entry_key text not null,
  action text not null check (action in ('created', 'updated', 'deleted', 'reordered', 'image-updated')),
  snapshot jsonb not null,
  changed_at timestamptz not null default now(),
  changed_by uuid references public.app_auth_users(id) on delete set null
);

create index if not exists uniform_guide_entries_section_order_idx
  on public.uniform_guide_entries(section_key, sort_order, title);
create index if not exists uniform_guide_revisions_changed_at_idx
  on public.uniform_guide_revisions(changed_at desc);

insert into public.uniform_guide_sections (section_key, label, description, sort_order)
values
  ('restricted-items', 'Restricted Items', 'Items prohibited or restricted during Main Operations.', 0),
  ('recruits', 'Recruits', 'Recruit and cadet uniforms, equipment, and approved loadouts.', 1),
  ('infantry', 'Infantry', 'Standard infantry uniforms and loadouts by rank.', 2),
  ('certifications', 'Certifications', 'Certification-specific uniforms, weapons, equipment, and loadout limits.', 3),
  ('dagger', 'Dagger', 'Dagger airborne uniforms and equipment by billet and rank.', 4),
  ('hammer', 'Hammer', 'Hammer aviation uniforms and loadouts by flight rank.', 5),
  ('zeus', 'Zeus', 'Approved Zeus appearance standards by qualification level.', 6),
  ('arc', 'ARC', 'ARC uniform reference and supporting documentation.', 7),
  ('longbow', 'Longbow', 'Longbow specialist uniforms and operational loadouts.', 8)
on conflict (section_key) do nothing;

