alter table public.uniform_guide_sections enable row level security;
alter table public.uniform_guide_entries enable row level security;
alter table public.uniform_guide_assets enable row level security;
alter table public.uniform_guide_revisions enable row level security;

revoke all on public.uniform_guide_sections from public;
revoke all on public.uniform_guide_entries from public;
revoke all on public.uniform_guide_assets from public;
revoke all on public.uniform_guide_revisions from public;

grant select, insert, update, delete on public.uniform_guide_sections to roster_app_runtime;
grant select, insert, update, delete on public.uniform_guide_entries to roster_app_runtime;
grant select, insert, update, delete on public.uniform_guide_assets to roster_app_runtime;
grant select, insert on public.uniform_guide_revisions to roster_app_runtime;
grant usage, select on sequence public.uniform_guide_revisions_id_seq to roster_app_runtime;

drop policy if exists "native runtime uniform guide sections" on public.uniform_guide_sections;
create policy "native runtime uniform guide sections"
  on public.uniform_guide_sections for all to roster_app_runtime using (true) with check (true);
drop policy if exists "native runtime uniform guide entries" on public.uniform_guide_entries;
create policy "native runtime uniform guide entries"
  on public.uniform_guide_entries for all to roster_app_runtime using (true) with check (true);
drop policy if exists "native runtime uniform guide assets" on public.uniform_guide_assets;
create policy "native runtime uniform guide assets"
  on public.uniform_guide_assets for all to roster_app_runtime using (true) with check (true);
drop policy if exists "native runtime uniform guide revisions" on public.uniform_guide_revisions;
create policy "native runtime uniform guide revisions"
  on public.uniform_guide_revisions for all to roster_app_runtime using (true) with check (true);

insert into public.app_page_permissions
  (permission_key, page_path, label, category, description)
values
  ('admin.uniform-guide', '/admin/uniform-guide', 'Uniform Guide', 'Systems',
   'Review and maintain the public uniform, equipment, and restricted-item guide.')
on conflict (permission_key) do update
set page_path = excluded.page_path,
    label = excluded.label,
    category = excluded.category,
    description = excluded.description,
    updated_at = now();

insert into public.user_page_permissions
  (user_id, permission_key, access_level, granted_by, updated_at)
select users.id, 'admin.uniform-guide', 'full', users.id, now()
from public.app_auth_users users
where lower(users.username) = 'akhari'
on conflict (user_id, permission_key) do update
set access_level = 'full',
    granted_by = excluded.granted_by,
    updated_at = now();
